let state = null;

export function initialize(element, dotNetRef, timeoutMs) {
    const events = ['mousemove', 'keydown', 'click', 'scroll', 'touchstart'];
    let timerId = null;
    let isIdle = false;

    function resetTimer() {
        if (timerId !== null) {
            clearTimeout(timerId);
        }

        if (isIdle) {
            isIdle = false;
            dotNetRef.invokeMethodAsync('NotifyActive');
        }

        timerId = setTimeout(() => {
            isIdle = true;
            dotNetRef.invokeMethodAsync('NotifyIdle');
        }, timeoutMs);
    }

    events.forEach(evt => element.addEventListener(evt, resetTimer, { passive: true }));

    // Start the initial timer
    timerId = setTimeout(() => {
        isIdle = true;
        dotNetRef.invokeMethodAsync('NotifyIdle');
    }, timeoutMs);

    state = { element, events, timerId, resetTimer };
}

export function dispose() {
    if (state) {
        clearTimeout(state.timerId);
        state.events.forEach(evt =>
            state.element.removeEventListener(evt, state.resetTimer)
        );
        state = null;
    }
}

